#include <cstdint>
#include <string>
#include <vector>

struct Snapshot
{
    std::uint32_t magic, version, size;
    std::uint64_t frame;
    float frameMs;
    std::int32_t floor, playerHp, playerMaxHp, monstersAlive;
};

std::vector<std::string> problems(const Snapshot& s, std::uint64_t previousFrame)
{
    if (s.magic != 0x54564C44u) return { "magic" };
    std::vector<std::string> found;
    if (s.version != 1) found.push_back("version");
    if (s.size < 48) found.push_back("size");
    if (s.frame < previousFrame) found.push_back("frame went backwards");
    if (!(s.frameMs > 0.0f && s.frameMs < 10000.0f)) found.push_back("frame time");     // NaN fails both comparisons
    if (s.floor < 1 || s.floor > 99) found.push_back("floor");
    if (s.playerMaxHp < 1 || s.playerMaxHp > 10000 || s.playerHp < 0 || s.playerHp > s.playerMaxHp) found.push_back("health");
    if (s.monstersAlive < 0 || s.monstersAlive > 10000) found.push_back("monsters");
    return found;
}

unitTests:
#include <limits>
using P = std::vector<std::string>;
static Snapshot good() { return Snapshot{ 0x54564C44u, 1, 64, 1000, 16.6f, 3, 14, 20, 6 }; }
TEST("a good snapshot") { CHECK(problems(good(), 999).empty()); }
TEST("wrong magic hides everything else") { Snapshot s{ good() }; s.magic = 0; s.version = 9; CHECK(problems(s, 0) == P({ "magic" })); }
TEST("several problems in order") { Snapshot s{ good() }; s.version = 2; s.floor = 0; s.monstersAlive = -1; CHECK(problems(s, 0) == P({ "version", "floor", "monsters" })); }
TEST("frame went backwards") { CHECK(problems(good(), 5000) == P({ "frame went backwards" })); }
TEST("health out of range") { Snapshot s{ good() }; s.playerHp = 25; CHECK(problems(s, 0) == P({ "health" })); s.playerHp = 5; s.playerMaxHp = 0; CHECK(problems(s, 0) == P({ "health" })); }
TEST("NaN frame time") { Snapshot s{ good() }; s.frameMs = std::numeric_limits<float>::quiet_NaN(); CHECK(problems(s, 0) == P({ "frame time" })); }
TEST("size too small") { Snapshot s{ good() }; s.size = 16; CHECK(problems(s, 0) == P({ "size" })); }

